From 88060c7f7fc64709b133fb075472b3890a0753a8 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 03:39:19 +0100
Subject: [PATCH] xdgactivation: tell the task manager which desktop file
 opened a window

When several desktop files start the same application, all its windows
share one app id. Remember the app id each activation token was created
with and send it in plasma-window-management for the window it shows.

BUG: 475736
---
 src/wayland/plasmawindowmanagement.cpp | 30 +++++++++++++++++++++++++-
 src/wayland/plasmawindowmanagement.h   |  1 +
 src/window.cpp                         | 14 ++++++++++++
 src/window.h                           |  8 +++++++
 src/xdgactivationv1.cpp                | 12 +++++++++++
 src/xdgactivationv1.h                  |  1 +
 6 files changed, 65 insertions(+), 1 deletion(-)

diff --git a/src/wayland/plasmawindowmanagement.cpp b/src/wayland/plasmawindowmanagement.cpp
index 6c1cfec022..e8456ca1ab 100644
--- a/src/wayland/plasmawindowmanagement.cpp
+++ b/src/wayland/plasmawindowmanagement.cpp
@@ -27,7 +27,7 @@
 namespace KWin
 {

-static const quint32 s_version = 23;
+static const quint32 s_version = 24;
 static const quint32 s_activationVersion = 1;

 class PlasmaWindowManagementInterfacePrivate : public QtWaylandServer::org_kde_plasma_window_management
@@ -80,6 +80,7 @@ public:
     void setApplicationMenuPaths(const QString &service, const QString &object);
     void setResourceName(const QString &resourceName);
     void setResourceClass(const QString &resourceClass);
+    void setLaunchAppId(const QString &appId);
     void sendInitialState(Resource *resource);
     wl_resource *resourceForParent(PlasmaWindowInterface *parent, Resource *child) const;
     void setClientGeometry(const Rect &geometry);
@@ -105,6 +106,7 @@ public:
     QString uuid;
     QString m_resourceName;
     QString m_resourceClass;
+    QString m_launchAppId;
     Rect clientGeometry;
     bool mapped = false;

@@ -422,6 +424,12 @@ void PlasmaWindowInterfacePrivate::sendInitialState(Resource *resource)
         }
     }

+    if (!m_launchAppId.isEmpty()) {
+        if (resource->version() >= ORG_KDE_PLASMA_WINDOW_LAUNCH_APP_ID_SINCE_VERSION) {
+            send_launch_app_id(resource->handle, m_launchAppId);
+        }
+    }
+
     if (clientGeometry.isValid() && resource->version() >= ORG_KDE_PLASMA_WINDOW_CLIENT_GEOMETRY_SINCE_VERSION) {
         send_client_geometry(resource->handle, clientGeometry.x(), clientGeometry.y(), clientGeometry.width(), clientGeometry.height());
     }
@@ -520,6 +528,21 @@ void PlasmaWindowInterfacePrivate::setResourceClass(const QString &resourceClass
     }
 }

+void PlasmaWindowInterfacePrivate::setLaunchAppId(const QString &appId)
+{
+    if (m_launchAppId == appId) {
+        return;
+    }
+    m_launchAppId = appId;
+
+    const auto clientResources = resourceMap();
+    for (auto resource : clientResources) {
+        if (resource->version() >= ORG_KDE_PLASMA_WINDOW_LAUNCH_APP_ID_SINCE_VERSION) {
+            send_launch_app_id(resource->handle, appId);
+        }
+    }
+}
+
 void PlasmaWindowInterfacePrivate::org_kde_plasma_window_get_icon(Resource *resource, int32_t fd)
 {
     QThreadPool::globalInstance()->start([fd, icon = m_icon]() {
@@ -934,6 +957,11 @@ void PlasmaWindowInterface::setResourceClass(const QString &resourceClass)
     d->setResourceClass(resourceClass);
 }

+void PlasmaWindowInterface::setLaunchAppId(const QString &appId)
+{
+    d->setLaunchAppId(appId);
+}
+
 void PlasmaWindowInterface::addPlasmaVirtualDesktop(const QString &id)
 {
     // don't add a desktop we're not sure it exists
diff --git a/src/wayland/plasmawindowmanagement.h b/src/wayland/plasmawindowmanagement.h
index 836943a238..130d28b513 100644
--- a/src/wayland/plasmawindowmanagement.h
+++ b/src/wayland/plasmawindowmanagement.h
@@ -125,6 +125,7 @@ public:
     void setResizable(bool set);
     void setResourceName(const QString &resourceName);
     void setResourceClass(const QString &resourceClass);
+    void setLaunchAppId(const QString &appId);
     /**
      * FIXME: still relevant with new desktops?
      */
diff --git a/src/window.cpp b/src/window.cpp
index 3136af6275..16c5f288f9 100644
--- a/src/window.cpp
+++ b/src/window.cpp
@@ -1779,6 +1779,7 @@ void Window::setupWindowManagementInterface()
     w->setSkipTaskbar(skipTaskbar());
     w->setSkipSwitcher(skipSwitcher());
     w->setPid(pid());
+    w->setLaunchAppId(launchAppId());
     w->setResizable(isResizable());
     w->setMovable(isMovable());
     w->setVirtualDesktopChangeable(true); // FIXME Matches X11Window::actionSupported(), but both should be implemented.
@@ -4627,6 +4628,19 @@ QString Window::activationToken() const
     return m_activationToken;
 }

+void Window::setLaunchAppId(const QString &appId)
+{
+    m_launchAppId = appId;
+    if (m_windowManagementInterface) {
+        m_windowManagementInterface->setLaunchAppId(appId);
+    }
