+
+QString Window::launchAppId() const
+{
+    return m_launchAppId;
+}
+
 bool Window::excludeFromCapture() const
 {
     return m_excludeFromCapture;
diff --git a/src/window.h b/src/window.h
index a4113ad7fa..a7e196560f 100644
--- a/src/window.h
+++ b/src/window.h
@@ -1585,6 +1585,13 @@ public:
     void setActivationToken(const QString &token);
     QString activationToken() const;

+    /**
+     * The app id of the activation token the window was activated with as it was first shown,
+     * that is the desktop file it was launched from.
+     */
+    void setLaunchAppId(const QString &appId);
+    QString launchAppId() const;
+
     bool excludeFromCapture() const;
     void setExcludeFromCapture(bool newExcludeFromCapture);

@@ -2105,6 +2112,7 @@ protected:
     QString m_description;

     QString m_activationToken;
+    QString m_launchAppId;
 };

 inline RectF Window::bufferGeometry() const
diff --git a/src/xdgactivationv1.cpp b/src/xdgactivationv1.cpp
index ce6cce956f..4816da8edf 100644
--- a/src/xdgactivationv1.cpp
+++ b/src/xdgactivationv1.cpp
@@ -105,6 +105,13 @@ QString XdgActivationV1Integration::requestToken(bool isPrivileged, SurfaceInter
         serial = input()->lastInteractionSerial();
     }
     workspace()->setActivationToken(newToken, serial, appId);
+    if (!appId.isEmpty()) {
+        // Remember the app id so that the window shown with this token knows which desktop file it was launched from.
+        if (m_tokenAppIds.size() >= 20) {
+            m_tokenAppIds.removeFirst();
+        }
+        m_tokenAppIds.append({newToken, appId});
+    }
     if (showNotify) {
         Q_EMIT effects->startupAdded(newToken, icon);
     }
@@ -122,6 +129,11 @@ void XdgActivationV1Integration::activateSurface(SurfaceInterface *surface, cons

     if (!window->readyForPainting()) {
         window->setActivationToken(token);
+        const auto it = std::ranges::find(m_tokenAppIds, token, &std::pair<QString, QString>::first);
+        if (it != m_tokenAppIds.end()) {
+            window->setLaunchAppId(it->second);
+            m_tokenAppIds.erase(it);
+        }
         return;
     }

diff --git a/src/xdgactivationv1.h b/src/xdgactivationv1.h
index c609d3cbdd..effdde53d7 100644
--- a/src/xdgactivationv1.h
+++ b/src/xdgactivationv1.h
@@ -44,6 +44,7 @@ private:

     QString m_lastToken;
     QString m_lastTokenAppId;
+    QList<std::pair<QString, QString>> m_tokenAppIds;
     std::unique_ptr<PlasmaWindowActivationInterface> m_activation;
 };

