+Name=Dolphin
+Exec=dolphin %u
+Icon=system-file-manager
+Type=Application
+NoDisplay=true
+MimeType=inode/directory;
diff --git a/libtaskmanager/autotests/data/applications/dolphin-home.desktop b/libtaskmanager/autotests/data/applications/dolphin-home.desktop
new file mode 100644
index 0000000000..8f6bcda4fd
--- /dev/null
+++ b/libtaskmanager/autotests/data/applications/dolphin-home.desktop
@@ -0,0 +1,7 @@
