diff --git a/libtaskmanager/autotests/tasktoolstest.cpp b/libtaskmanager/autotests/tasktoolstest.cpp
index 0f325dd616..a2ee7aa18e 100644
--- a/libtaskmanager/autotests/tasktoolstest.cpp
+++ b/libtaskmanager/autotests/tasktoolstest.cpp
@@ -33,6 +33,8 @@ private Q_SLOTS:
     void shouldCompareLauncherUrls();
     void testServiceFromMetadata();
     void testServiceFromMetadata_data();
+    void testServiceFromLaunchAppId();
+    void testServiceFromLaunchAppId_data();
     void testServiceFromCmdLine();
     void testServiceFromCmdLine_data();
     void testServiceForUrl();
@@ -68,6 +70,9 @@ void TaskToolsTest::initTestCase()
     QFile::copy(QFINDTESTDATA("data/applications/chrome-mlbnfdlkgcjnjnjfliemlppklmpchgib-Default.desktop"),
                 dataDir + QLatin1String("/applications/chrome-mlbnfdlkgcjnjnjfliemlppklmpchgib-Default.desktop"));
     QFile::copy(QFINDTESTDATA("data/applications/marisa..desktop"), dataDir + QLatin1String("/applications/marisa..desktop"));
+    QFile::copy(QFINDTESTDATA("data/applications/dolphin-home.desktop"), dataDir + QLatin1String("/applications/dolphin-home.desktop"));
+    QFile::copy(QFINDTESTDATA("data/applications/dolphin-webapp.desktop"), dataDir + QLatin1String("/applications/dolphin-webapp.desktop"));
+    QFile::copy(QFINDTESTDATA("data/applications/dolphin-handler.desktop"), dataDir + QLatin1String("/applications/dolphin-handler.desktop"));

     QFile::copy(QFINDTESTDATA("data/applications/kcm_kdeconnect.desktop"), dataDir + QLatin1String("/kservices6/kcm_kdeconnect.desktop"));

@@ -190,6 +195,31 @@ void TaskToolsTest::testServiceFromMetadata_data()
     QTest::addRow("Empty appId and xWindowsWMClassName, don't match marisa..desktop") << QString() << QString() << QString() << QString();
 }

+void TaskToolsTest::testServiceFromLaunchAppId()
+{
+    QFETCH(QString, launchAppId);
+    QFETCH(QString, resultStorageId);
+
+    const auto service = serviceFromMetadata(u"org.kde.dolphin"_s, 0, QString(), QString(), launchAppId);
+
+    QCOMPARE(service->storageId(), resultStorageId);
+}
+
+void TaskToolsTest::testServiceFromLaunchAppId_data()
+{
+    QTest::addColumn<QString>("launchAppId");
+    QTest::addColumn<QString>("resultStorageId");
+
+    QTest::addRow("not launched") << QString() << "org.kde.dolphin.desktop";
+    QTest::addRow("same desktop file") << "org.kde.dolphin" << "org.kde.dolphin.desktop";
+    QTest::addRow("other desktop file, same executable") << "dolphin-home" << "dolphin-home.desktop";
+    QTest::addRow("other desktop file with extension") << "dolphin-home.desktop" << "dolphin-home.desktop";
+    QTest::addRow("other executable") << "org.kde.konversation" << "org.kde.dolphin.desktop";
+    QTest::addRow("other StartupWMClass") << "dolphin-webapp" << "org.kde.dolphin.desktop";
+    QTest::addRow("hidden handler") << "dolphin-handler" << "org.kde.dolphin.desktop";
+    QTest::addRow("unknown desktop file") << "does-not-exist" << "org.kde.dolphin.desktop";
+}
+
 void TaskToolsTest::testServiceFromCmdLine_data()
 {
     QTest::addColumn<QString>("cmdLine");
diff --git a/libtaskmanager/tasktools.cpp b/libtaskmanager/tasktools.cpp
index 67fc843756..8474ac4c34 100644
--- a/libtaskmanager/tasktools.cpp
+++ b/libtaskmanager/tasktools.cpp
@@ -20,6 +20,7 @@
 #include <PlasmaActivities/ResourceInstance>

 #include <KIO/ApplicationLauncherJob>
+#include <KIO/DesktopExecParser>
 #include <KIO/OpenUrlJob>

 #include <QDir>
@@ -113,7 +114,8 @@ AppData appDataFromUrl(const QUrl &url, const QIcon &fallbackIcon)
     return AppData{.icon = fallbackIcon, .url = url, .service = KService::Ptr(new KService(url.fileName(), QString(), fallbackIcon.name()))};
 }

-KService::Ptr serviceFromMetadata(const QString &appId, quint32 pid, const QString &xWindowsWMClassName, const QString &xWindowsWMClassClass)
+KService::Ptr
+serviceFromMetadata(const QString &appId, quint32 pid, const QString &xWindowsWMClassName, const QString &xWindowsWMClassClass, const QString &launchAppId)
 {
     // The code below this function goes on a hunt for services based on the metadata
     // that has been passed in. Occasionally, it will find more than one matching
@@ -147,6 +149,29 @@ KService::Ptr serviceFromMetadata(const QString &appId, quint32 pid, const QStri
         }
     };

+    // Several desktop files can start the same application (e.g. with other arguments and another icon), and then
+    // its windows share the same metadata. Prefer the desktop file the window was launched from.
+    auto preferLaunchService = [&](const KService::Ptr &service) -> KService::Ptr {
+        if (launchAppId.isEmpty()) {
+            return service;
+        }
+
+        const KService::Ptr launchService = KService::serviceByStorageId(launchAppId);
+        if (!launchService || launchService->storageId() == service->storageId() || !launchService->isApplication() || launchService->noDisplay()) {
+            return service;
+        }
+
+        const QString startupWMClass = launchService->property<QString>(QStringLiteral("StartupWMClass"));
+        const bool wmClassMatches = startupWMClass.isEmpty() || startupWMClass.compare(appId, Qt::CaseInsensitive) == 0
+            || startupWMClass.compare(xWindowsWMClassName, Qt::CaseInsensitive) == 0 || startupWMClass.compare(xWindowsWMClassClass, Qt::CaseInsensitive) == 0;
+        const QString executable = KIO::DesktopExecParser::executableName(service->exec());
+        if (wmClassMatches && !executable.isEmpty() && KIO::DesktopExecParser::executableName(launchService->exec()) == executable) {
+            return launchService;
+        }
+
+        return service;
+    };
+
     if (!appId.isEmpty()) {
         auto services = KApplicationTrader::query([&appId](const KService::Ptr &service) {
             return service->desktopEntryName().compare(appId, Qt::CaseInsensitive) == 0;
@@ -154,7 +179,7 @@ KService::Ptr serviceFromMetadata(const QString &appId, quint32 pid, const QStri
         sortServicesByMenuId(services, appId);

         if (!services.isEmpty()) {
-            return services.first();
+            return preferLaunchService(services.first());
         }

         // The appId looks like a path.
@@ -183,7 +208,7 @@ KService::Ptr serviceFromMetadata(const QString &appId, quint32 pid, const QStri
         sortServicesByMenuId(services, xWindowsWMClassName);

         if (!services.isEmpty()) {
-            return services.first();
+            return preferLaunchService(services.first());
         }
     }

@@ -194,7 +219,7 @@ KService::Ptr serviceFromMetadata(const QString &appId, quint32 pid, const QStri
         sortServicesByMenuId(services, xWindowsWMClassClass);

         if (!services.isEmpty()) {
-            return services.first();
+            return preferLaunchService(services.first());
         }
     }

diff --git a/libtaskmanager/tasktools.h b/libtaskmanager/tasktools.h
index ae61e25b37..f364348d9b 100644
--- a/libtaskmanager/tasktools.h
+++ b/libtaskmanager/tasktools.h
@@ -72,10 +72,15 @@ TASKMANAGER_EXPORT KService::List servicesFromPid(quint32 pid);
